(function(){'use strict';
 class WaveformView{
  constructor(){this.worker=null;this.input=null;this.jobs=new Map();this.memberJobs=new Map();this.featureJobs=new Map();this.counter=0;this.ready=false;}
  load(input){if(this.input===input)return;this.worker?.terminate();this.jobs.clear();this.memberJobs.clear();this.input=input;this.ready=false;this.error=null;this.worker=new Worker('waveform-worker.js?v=7');this.worker.onmessage=({data:m})=>{if(m.type==='ready'){this.ready=true;this.updated?.();for(const j of this.jobs.values())this.send(j);for(const j of this.memberJobs.values())this.worker.postMessage(j.request);for(const id of this.featureJobs.keys())this.worker.postMessage({type:'features',id});}else if(m.type==='features'){const callback=this.featureJobs.get(m.id);this.featureJobs.delete(m.id);callback?.(m);}else if(m.type==='members'){const j=this.memberJobs.get(m.id);this.memberJobs.delete(m.id);j?.callback(m);}else if(m.type==='error'){this.error=m.error;this.updated?.();for(const callback of this.featureJobs.values())callback({error:m.error});this.featureJobs.clear();for(const j of this.memberJobs.values())j.callback({error:m.error});this.memberJobs.clear();const list=m.id?[this.jobs.get(m.id)]:this.jobs.values();for(const j of list)if(j)j.status.textContent='Waveform view unavailable: '+m.error;}else if(m.type==='image'){const j=this.jobs.get(m.id);if(j&&j.canvas.isConnected){j.canvas.getContext('2d').drawImage(m.bitmap,0,0);j.status.textContent=m.sampled?`${m.drawn.toLocaleString()} sampled / ${m.total.toLocaleString()} members · up to 24 real spikes per cluster`:m.full?(m.done?`All ${m.drawn.toLocaleString()} member waveforms`:`Drawing all members… ${m.drawn.toLocaleString()} / ${m.total.toLocaleString()}`):`${m.drawn.toLocaleString()} stored samples; legacy package does not contain all waveforms`;j.canvas.dataset.yMin=String(m.low);j.canvas.dataset.yMax=String(m.high);j.canvas.dataset.complete=String(m.done);j.canvas.dataset.drawn=m.drawn;j.canvas.dataset.full=String(m.full);j.canvas.dataset.sampled=String(!!m.sampled);if(m.done)j.onDone?.();}m.bitmap.close();}};
   this.worker.onerror=e=>{this.error=e.message;this.updated?.();for(const callback of this.featureJobs.values())callback({error:e.message});this.featureJobs.clear();for(const j of this.jobs.values())j.status.textContent='Waveform view unavailable: '+e.message;};
   this.worker.postMessage({type:'load',data:{n_samples:input.data.n_samples,times:input.times,atoms:input.data.atoms,arrays:{waveforms:input.data.arrays.waveforms,atom_index:input.data.arrays.atom_index}}});
  }
  features(callback){const id=++this.counter;if(this.error){callback({error:this.error});return;}this.featureJobs.set(id,callback);if(this.ready)this.worker.postMessage({type:'features',id});}
  members(labels,axisGroups,cluster,page,pageSize,order,callback){for(const [id,j] of this.jobs)if(!j.canvas.isConnected){this.worker.postMessage({type:'cancel',id});this.jobs.delete(id);}const id=++this.counter,request={type:'members',id,labels:labels.slice(),axisGroups,cluster,page,pageSize,order};if(this.error){callback({error:this.error});return;}this.memberJobs.set(id,{request,callback});if(this.ready)this.worker.postMessage(request);}
  cancel(canvas){for(const [id,j] of this.jobs)if(j.canvas===canvas){this.worker.postMessage({type:'cancel',id});this.jobs.delete(id);}}
  send(j){if(!j.canvas.isConnected)return;this.worker.postMessage({type:'draw',id:j.id,width:j.canvas.width,height:j.canvas.height,labels:j.labels,groups:j.groups,axisGroups:j.axisGroups,mini:j.mini,zoom:j.zoom,opacity:j.opacity,coverage:j.coverage,row_labels:j.rowLabels,duration:(this.input.data.n_samples-1)/this.input.data.sampling_rate_hz*1000});}
  draw(canvas,status,labels,groups,mini=false,zoom=1,onDone=null,axisGroups=null,opacity=null,coverage='all',rowLabels={}){for(const [id,j] of this.jobs)if(!j.canvas.isConnected||j.canvas===canvas){this.worker.postMessage({type:'cancel',id});this.jobs.delete(id);}const id=++this.counter,rect=canvas.getBoundingClientRect();canvas.width=Math.max(130,Math.round(rect.width||600));canvas.height=mini?112:300;canvas.dataset.complete='false';canvas.dataset.clusterIds=JSON.stringify(groups.map(g=>g.id));canvas.dataset.axisClusterIds=JSON.stringify((axisGroups||groups).map(g=>g.id));const job={id,canvas,status,labels:labels.slice(),groups,axisGroups:axisGroups||groups,mini,zoom,opacity,coverage,onDone,rowLabels};this.jobs.set(id,job);status.textContent=this.error?'Waveform view unavailable: '+this.error:this.ready?'Drawing all member waveforms…':'Loading waveform data…';if(this.ready)this.send(job);}
 }
 window.WaveformView=WaveformView;
})();
